import{_ as c,r as e,o as l,c as i,e as t,a as s,d as n,s as r}from"./chunks/framework.CXcwiNg-.js";const m=JSON.parse('{"title":"存储 - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"配置","slug":"配置","link":"#配置","children":[{"level":4,"title":"本地驱动程序","slug":"本地驱动程序","link":"#本地驱动程序","children":[]},{"level":4,"title":"其他驱动程序先决条件","slug":"其他驱动程序先决条件","link":"#其他驱动程序先决条件","children":[]}]},{"level":2,"title":"基本用法","slug":"基本用法","link":"#基本用法","children":[{"level":3,"title":"获取磁盘实例","slug":"获取磁盘实例","link":"#获取磁盘实例","children":[]},{"level":3,"title":"获取文件","slug":"获取文件","link":"#获取文件","children":[{"level":4,"title":"文件元信息","slug":"文件元信息","link":"#文件元信息","children":[]}]},{"level":3,"title":"存储文件","slug":"存储文件","link":"#存储文件","children":[{"level":4,"title":"向文件前置 / 追加内容","slug":"向文件前置-追加内容","link":"#向文件前置-追加内容","children":[]}]},{"level":3,"title":"删除文件","slug":"删除文件","link":"#删除文件","children":[]},{"level":3,"title":"目录","slug":"目录","link":"#目录","children":[{"level":4,"title":"获取目录中的所有文件","slug":"获取目录中的所有文件","link":"#获取目录中的所有文件","children":[]},{"level":4,"title":"获取目录中的所有子目录","slug":"获取目录中的所有子目录","link":"#获取目录中的所有子目录","children":[]},{"level":4,"title":"创建目录","slug":"创建目录","link":"#创建目录","children":[]},{"level":4,"title":"删除目录","slug":"删除目录","link":"#删除目录","children":[]}]}]}],"relativePath":"3.x/zh-cn/extend/services/storage.md","filePath":"3.x/zh-cn/extend/services/storage.md"}'),u={name:"3.x/zh-cn/extend/services/storage.md"};function d(k,a,g,h,f,v){const p=e("pre-heading"),o=e("post-heading");return l(),i("div",null,[t(p),a[0]||(a[0]=s("h1",null,"存储",-1)),t(o),a[1]||(a[1]=s("p",null,[n("October CMS 借助 Laravel 和出色的 "),s("a",{href:"https://github.com/thephpleague/flysystem",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("Flysystem"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),s("span",{class:"sr-only"},"(opens new window)")])]),n(" PHP 包提供了强大的文件系统抽象。Flysystem 集成提供了简单易用的驱动程序，用于处理本地文件系统和 Amazon S3。更棒的是，在这些存储选项之间切换非常简单，因为每个系统的 API 保持不变。")],-1)),a[2]||(a[2]=r(`<h2 id="配置"><a href="#配置" class="header-anchor">#</a> 配置</h2><p>文件系统配置文件位于 <code>config/filesystems.php</code>。在此文件中，你可以配置所有的&quot;磁盘&quot;。每个磁盘代表一个特定的存储驱动程序和存储位置。配置文件中包含了每个支持的驱动程序的示例配置。因此，只需修改配置以反映你的存储偏好和凭据即可。</p><p>当然，你可以配置任意数量的磁盘，甚至可以有多个使用相同驱动程序的磁盘。</p><h4 id="本地驱动程序"><a href="#本地驱动程序" class="header-anchor">#</a> 本地驱动程序</h4><p>使用 <code>local</code> 驱动程序时，请注意所有文件操作都相对于配置文件中定义的 <code>root</code> 目录。默认情况下，此值设置为 <code>storage/app</code> 目录。因此，以下方法将在 <code>storage/app/file.txt</code> 中存储文件：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">disk</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;local&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.txt&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Contents&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="其他驱动程序先决条件"><a href="#其他驱动程序先决条件" class="header-anchor">#</a> 其他驱动程序先决条件</h4><p>在使用 S3 驱动程序之前，你需要通过 Composer 包管理器安装 Flysystem S3 包。</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">composer</span> require league/flysystem-aws-s3-v3 <span class="token string">&quot;^3.0&quot;</span>
</code></pre></div><p>S3 驱动程序配置信息位于你的 <code>config/filesystems.php</code> 配置文件中。此文件包含 S3 驱动程序的示例配置数组。你可以使用自己的 S3 配置和凭据自由修改此数组。</p><h2 id="基本用法"><a href="#基本用法" class="header-anchor">#</a> 基本用法</h2><h3 id="获取磁盘实例"><a href="#获取磁盘实例" class="header-anchor">#</a> 获取磁盘实例</h3><p><code>Storage</code> 门面可用于与你配置的任何磁盘交互。例如，你可以使用门面上的 <code>put</code> 方法将头像存储在默认磁盘上。如果你在没有先调用 <code>disk</code> 方法的情况下调用 <code>Storage</code> 门面上的方法，该方法调用将自动传递给默认磁盘：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token variable">$id</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span>
    <span class="token string single-quoted-string">&#39;avatars/&#39;</span><span class="token operator">.</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">,</span>
    <span class="token function">file_get_contents</span><span class="token punctuation">(</span><span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;avatar&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">getRealPath</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>使用多个磁盘时，你可以使用 <code>Storage</code> 门面上的 <code>disk</code> 方法访问特定磁盘。当然，你可以继续链式调用方法以在磁盘上执行操作：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$disk</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">disk</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;s3&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$contents</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">disk</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;local&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">)</span>
</code></pre></div><h3 id="获取文件"><a href="#获取文件" class="header-anchor">#</a> 获取文件</h3><p><code>get</code> 方法可用于获取给定文件的内容。该方法将返回文件的原始字符串内容：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$contents</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>exists</code> 方法可用于确定给定文件是否存在于磁盘上：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$exists</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">disk</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;s3&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">exists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="文件元信息"><a href="#文件元信息" class="header-anchor">#</a> 文件元信息</h4><p><code>size</code> 方法可用于获取文件的大小（以字节为单位）：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$size</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">size</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file1.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>lastModified</code> 方法返回文件最后修改时间的 UNIX 时间戳：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$time</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">lastModified</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file1.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="存储文件"><a href="#存储文件" class="header-anchor">#</a> 存储文件</h3><p><code>put</code> 方法可用于在磁盘上存储文件。你也可以将 PHP <code>resource</code> 传递给 <code>put</code> 方法，它将使用 Flysystem 的底层流支持。在处理大文件时，强烈建议使用流：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">,</span> <span class="token variable">$contents</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">,</span> <span class="token variable">$resource</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>copy</code> 方法可用于将现有文件复制到磁盘上的新位置：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">copy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;old/file1.jpg&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;new/file1.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>move</code> 方法可用于将现有文件移动到新位置：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">move</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;old/file1.jpg&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;new/file1.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="向文件前置-追加内容"><a href="#向文件前置-追加内容" class="header-anchor">#</a> 向文件前置 / 追加内容</h4><p><code>prepend</code> 和 <code>append</code> 方法允许你轻松地在文件的开头或结尾插入内容：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">prepend</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.log&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Prepended Text&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">append</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.log&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Appended Text&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="删除文件"><a href="#删除文件" class="header-anchor">#</a> 删除文件</h3><p><code>delete</code> 方法接受单个文件名或要从磁盘中移除的文件数组：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;file1.jpg&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;file2.jpg&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="目录"><a href="#目录" class="header-anchor">#</a> 目录</h3><h4 id="获取目录中的所有文件"><a href="#获取目录中的所有文件" class="header-anchor">#</a> 获取目录中的所有文件</h4><p><code>files</code> 方法返回给定目录中所有文件的数组。如果你想获取给定目录（包括所有子目录）中所有文件的列表，可以使用 <code>allFiles</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$files</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">files</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$files</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">allFiles</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="获取目录中的所有子目录"><a href="#获取目录中的所有子目录" class="header-anchor">#</a> 获取目录中的所有子目录</h4><p><code>directories</code> 方法返回给定目录中所有目录的数组。此外，你可以使用 <code>allDirectories</code> 方法获取给定目录及其所有子目录中的所有目录列表：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$directories</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">directories</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 递归...</span>
<span class="token variable">$directories</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">allDirectories</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="创建目录"><a href="#创建目录" class="header-anchor">#</a> 创建目录</h4><p><code>makeDirectory</code> 方法将创建给定的目录，包括任何所需的子目录：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">makeDirectory</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="删除目录"><a href="#删除目录" class="header-anchor">#</a> 删除目录</h4><p>最后，<code>deleteDirectory</code> 可用于从磁盘中移除目录及其所有文件：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">deleteDirectory</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,52))])}const S=c(u,[["render",d]]);export{m as __pageData,S as default};
